insert into public.experiments(slug,kind,topic,title,icon,levels,goal,difficulty,minutes,adult,learn,materials,safety,steps,expect,happened,why,learned,acts,sheet_url,wiki_slug,links,adapt,review_note,safety_reviewed,status,sort_order) values
('ex-sink-float','experiment','water','يطفو أم يغرق؟','x_water',array['a4','a5','a6','g1','g2','g3','g4']::text[],'أن أتوقع ثم أجرّب أي الأشياء تطفو على الماء وأيها تغرق.',1,15,'near',array['أن بعض الأشياء تطفو وبعضها يغرق.','أن أتوقع النتيجة ثم أتأكد بالتجربة.']::text[],$j$[["حوض أو وعاء كبير فيه ماء", "x_bucket"], ["كرة بلاستيكية خفيفة", "i_balloon"], ["قطعة إسفنج كبيرة", "x_sheet"], ["ملعقة خشبية كبيرة", "x_spoon"], ["حجر كبير بحجم الكف", "x_stone"], ["سيارة لعبة بلاستيكية كبيرة", "1f697"], ["منشفة", "x_sheet"]]$j$::jsonb,array['نستعمل أشياء كبيرة فقط، ولا نستعمل أشياء صغيرة قد يبتلعها الطفل.','يبقى شخص كبير بجانب الطفل وهو قرب الماء.','نفرش منشفة على الأرض ونمسح الماء المسكوب حتى لا ننزلق.','لا نضع الأشياء في الفم، ونغسل أيدينا بعد التجربة.']::text[],$j$[["نملأ الحوض بالماء حتى نصفه تقريبًا ونضعه على منشفة.", "x_bucket"], ["نضع الأشياء أمامنا ونتوقع: أيها سيطفو وأيها سيغرق؟ ونسجل التوقع على الورقة.", "i_notebook"], ["نضع شيئًا واحدًا في كل مرة برفق في الماء.", "x_hand"], ["نلاحظ هل طفا الشيء أم غرق، ونعلّم النتيجة.", "1f441"], ["نخرج الأشياء ونجففها ونرتبها في مجموعتين: يطفو ويغرق.", "x_sheet"]]$j$::jsonb,'الكرة والإسفنج والملعقة الخشبية قد تطفو. أما الحجر الكبير فيغرق. وقد نتفاجأ بشيء لم نتوقعه.','طفت الكرة البلاستيكية والإسفنجة والملعقة الخشبية، وغرق الحجر. وسيارة اللعبة الكبيرة قد تطفو أو تغرق بحسب نوعها.','الشيء الخفيف مقارنة بحجمه، أو الذي فيه هواء، يطفو. والشيء الثقيل مقارنة بحجمه، مثل الحجر، يغرق. وليس الحجم الكبير هو السبب بل نوع المادة وما فيها من هواء.',array['بعض الأشياء تطفو على الماء وبعضها يغرق.','نوع المادة وما فيها من هواء يؤثران في الطفو.','نتوقع أولًا ثم نجرّب لنتأكد.']::text[],$j$[{"k": "mc", "q": "ماذا حدث للحجر الكبير في الماء؟", "o": ["غرق", "طفا", "ذاب"], "a": 0, "ts": [1, 2]}, {"k": "sort", "g": ["يطفو", "يغرق"], "i": [["الكرة", 0, "i_balloon"], ["الإسفنجة", 0, "x_sheet"], ["الحجر", 1, "x_stone"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "الشيء الثقيل دائمًا يغرق مهما كان.", "a": false, "ts": [3]}, {"k": "mc", "q": "لماذا نتوقع النتيجة قبل التجربة؟", "o": ["لنقارن توقعنا بما حدث ونتعلم", "لنخمّن فقط", "لا فائدة منه"], "a": 0, "ts": [2, 3]}, {"k": "fill", "q": "الشيء الذي فيه ___ كثير قد يطفو.", "o": ["هواء", "حجارة", "رمل"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-sink-float-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["يطفو"]}, {"type": "stories", "q": ["قطرةِ الماء"]}]$j$::jsonb,'في الأعمار الصغيرة يضع الكبير الأشياء ويسأل الطفل: ماذا ترى؟ وفي الصفوف الأكبر يسجل الطفل توقعه ونتيجته ويشرح السبب.','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',1),
('ex-dissolve','experiment','water','ماذا يذوب في الماء؟','1f4a7',array['a5','a6','g1','g2','g3','g4']::text[],'أن ألاحظ أن بعض المواد تذوب في الماء وبعضها لا يذوب.',2,20,'near',array['أن بعض المواد تذوب في الماء وبعضها لا يذوب.','أن أقارن بين المواد وأسجل ملاحظاتي.']::text[],$j$[["أربعة أكواب بلاستيكية شفافة", "x_jar"], ["ماء عادي", "x_water"], ["ملعقة سكر", "1f36c"], ["ملعقة ملح", "x_spoon"], ["ملعقة رمل نظيف", "x_soil"], ["ملعقة للتحريك", "x_spoon"]]$j$::jsonb,array['لا نذوق أي مادة في التجربة ولا نشربها.','لا نستعمل أكواب التجربة للأكل أو الشرب بعدها.','يبقى شخص كبير مع الطفل، ونفرش منشفة على الطاولة.','نغسل أيدينا بعد التجربة.']::text[],$j$[["نملأ ثلاثة أكواب بالماء إلى النصف، والكوب الرابع نتركه للمقارنة.", "x_jar"], ["نتوقع: أي المواد ستختفي في الماء؟", "i_notebook"], ["نضع ملعقة سكر في الكوب الأول، وملعقة ملح في الثاني، وملعقة رمل في الثالث.", "x_spoon"], ["نحرّك كل كوب بهدوء مدة قصيرة ثم ننتظر قليلًا.", "x_spoon"], ["ننظر إلى كل كوب ونقارن بالكوب الرابع، ونسجل ما لاحظناه.", "1f441"]]$j$::jsonb,'قد نتوقع أن تختفي بعض المواد في الماء.','اختفى السكر والملح بعد التحريك وصار الماء صافيًا (ذابا في الماء). أما الرمل فبقي مرئيًا وترسّب في قاع الكوب.','عندما تذوب المادة تنفصل إلى أجزاء صغيرة جدًا لا نراها، وتتوزع بين جزيئات الماء. أما الرمل فأجزاؤه كبيرة لا تذوب، فتبقى وتنزل إلى القاع.',array['بعض المواد تذوب في الماء مثل السكر والملح.','بعض المواد لا تذوب مثل الرمل.','لا نذوق المواد في التجارب.']::text[],$j$[{"k": "match", "p": [["1f36c", "سكر: يذوب"], ["x_soil", "رمل: لا يذوب"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا حدث للرمل في الماء؟", "o": ["بقي وترسّب", "ذاب", "تحول إلى سكر"], "a": 0, "ts": [1, 2, 3]}, {"k": "tf", "q": "نشرب الماء الذي جرّبنا فيه السكر والملح.", "a": false, "ts": [1, 2, 3]}, {"k": "fill", "q": "الملح والسكر ___ في الماء.", "o": ["يذوبان", "يطفوان", "يتجمدان"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا نحتاج كوبًا فيه ماء فقط؟", "o": ["للمقارنة", "للشرب", "لا حاجة له"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-dissolve-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["يطفو"]}]$j$::jsonb,'تنفذ كل مادة في كوب منفصل ليسهل المقارنة.','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',2),
('ex-ice-melt','experiment','water','ماذا يحدث للثلج؟','x_ice',array['a5','a6','g1','g2','g3','g4']::text[],'أن ألاحظ تحوّل الماء إلى ثلج ثم عودته ماءً.',2,30,'required',array['أن الماء يتحول إلى ثلج عندما يبرد كثيرًا.','أن الثلج يعود ماءً عندما يدفأ الجو من حوله.']::text[],$j$[["قالب ثلج وماء", "x_ice"], ["وعاءان شفافان", "x_jar"], ["مكان بعيد عن الشمس المباشرة ومكان مشمس", "x_sunrise"], ["ساعة أو مؤقت", "23f0"], ["منشفة", "x_sheet"]]$j$::jsonb,array['الكبير هو الذي يضع القالب في المُجمّد ويخرجه، والطفل لا يفتح المُجمّد بمفرده.','لا نضع مكعبات الثلج في الفم، فقد تؤذي الأسنان وقد تسبب الاختناق.','نمسح الماء المسكوب فورًا.','نغسل أيدينا بعد التجربة.']::text[],$j$[["يملأ الكبير قالب الثلج بالماء ويضعه في المُجمّد حتى اليوم التالي، والطفل يلاحظ شكل الماء قبل التجميد.", "x_water"], ["في اليوم التالي يخرج الكبير القالب، ونلمس المكعب برفق بإصبع واحد لنحس ببرودته.", "x_ice"], ["نضع مكعبًا في كل وعاء: وعاء في مكان مشمس ووعاء في مكان ظليل.", "x_jar"], ["نكتب الوقت ونراقب كل بضع دقائق ماذا يحدث.", "23f0"], ["نسجل أي وعاء ذاب فيه الثلج أولًا.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن يذوب الثلج أسرع في المكان المشمس.','تحوّل الماء إلى ثلج صلب في المُجمّد. وبعد وضعه خارجه بدأ يذوب ويتحول ماءً، وذاب أسرع في المكان الدافئ المشمس.','عندما يبرد الماء كثيرًا يتجمد ويصير صلبًا، وعندما يصل إليه الدفء يذوب ويعود سائلًا. ويذوب الثلج أسرع حيث الجو أدفأ.',array['الماء يتجمد عند البرودة الشديدة.','الثلج يذوب ويعود ماءً عند الدفء.','للماء حالتان رأيناهما: صلب وسائل.']::text[],$j$[{"k": "mc", "q": "ماذا يصبح الثلج عندما يدفأ الجو من حوله؟", "o": ["ماءً", "رملًا", "حجرًا"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "يذوب الثلج أسرع في المكان الدافئ.", "a": true, "ts": [2, 3]}, {"k": "match", "p": [["x_ice", "ثلج: صلب"], ["x_water", "ماء: سائل"]], "ts": [1, 2, 3]}, {"k": "fill", "q": "يتحول الماء إلى ثلج عندما ___ كثيرًا.", "o": ["يبرد", "يتحرك", "يتلوث"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "أين نضع مكعب الثلج ليذوب أسرع؟", "o": ["في مكان دافئ", "في المُجمّد", "في كيس مغلق في المُجمّد"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-ice-melt-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["يطفو"]}]$j$::jsonb,'الكبير ينفذ خطوات المُجمّد، والطفل يراقب ويسجل.','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',3),
('ex-water-cycle-bag','experiment','water','دورة الماء في كيس','1f327',array['a6','g1','g2','g3','g4']::text[],'أن أرى كيف يتحرك الماء من الأسفل إلى الأعلى ويعود قطرات.',3,15,'required',array['أن الماء يتبخر ثم يتكاثف ثم يعود قطرات.','أن أتابع تجربة لعدة ساعات وأسجل ملاحظاتي.']::text[],$j$[["كيس شفاف بسحاب متين", "x_sheet"], ["قليل من الماء (ربع كوب)", "x_water"], ["شريط لاصق", "x_paper"], ["نافذة تدخلها الشمس", "x_sunrise"]]$j$::jsonb,array['الكيس البلاستيكي ليس لعبة: لا نضعه قرب وجه الطفل ولا نتركه في يده.','الكبير يغلق الكيس ويلصقه، ويعلّقه في مكان بعيد عن متناول الصغار.','نراقب من بعيد ولا نفتح الكيس إلا بعد انتهاء التجربة.','ننظف أي ماء ينسكب.']::text[],$j$[["يضع الكبير ربع كوب ماء في الكيس ويغلقه جيدًا.", "x_water"], ["يلصق الكبير الكيس على نافذة مشمسة ويرتفع به قليلًا عن الأرض.", "x_paper"], ["نرسم على الورقة مكان الماء قبل البدء.", "i_notebook"], ["ننظر إلى الكيس كل ساعة ونسجل ماذا نرى على الجدار العلوي للكيس.", "1f441"], ["في آخر اليوم نرسم ما حدث.", "i_pencil"]]$j$::jsonb,'قد نتوقع أن نرى قطرات صغيرة على الجزء العلوي من الكيس.','ظهرت قطرات صغيرة على جدار الكيس من الداخل، وبعد وقت قد تنزل قطرات إلى الأسفل مثل المطر الصغير.','تدفئ الشمس الماء قليلًا فيتحول جزء منه إلى بخار غير مرئي (تبخر). ويبرد البخار عند السطح الأقل حرارة فيتحول إلى قطرات (تكاثف). وهكذا يحدث في الطبيعة عندما تتكوّن السحب ثم ينزل المطر.',array['الماء يتبخر ثم يتكاثف ثم يعود قطرات.','دورة الماء تتكرر في الطبيعة.','الشمس هي التي تحرّك دورة الماء.']::text[],$j$[{"k": "mc", "q": "ماذا نسمي تحول الماء إلى بخار؟", "o": ["تبخر", "تجمد", "ذوبان"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "ماذا ظهر على جدار الكيس؟", "o": ["قطرات ماء", "ثلج", "رمل"], "a": 0, "ts": [1, 2, 3]}, {"k": "tf", "q": "الشمس تساعد على تبخر الماء.", "a": true, "ts": [2, 3]}, {"k": "match", "p": [["x_water", "ماء"], ["2601", "سحابة"], ["1f327", "مطر"], ["2600", "شمس"]], "ts": [1, 2, 3]}, {"k": "fill", "q": "يتحول البخار إلى قطرات في عملية اسمها ___.", "o": ["التكاثف", "التبخر", "الذوبان"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-water-cycle-bag-sheet.pdf','wk-water',$j$[{"type": "stories", "q": ["قطرةِ الماء"]}]$j$::jsonb,'الكبير يتولى الكيس كاملًا، والطفل يراقب ويرسم.','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',4),
('ex-water-flow','experiment','water','الماء يجري إلى الأسفل','1f4a7',array['a3','a4','a5','a6','g1','g2']::text[],'أن ألاحظ كيف يتحرك الماء على سطح مائل.',1,15,'near',array['أن الماء يجري من الأعلى إلى الأسفل.','أن أقارن بين سطح مائل وسطح مستوٍ.']::text[],$j$[["صينية كبيرة", "x_box"], ["كوب ماء صغير", "x_jar"], ["كتاب سميك لرفع طرف الصينية", "i_book"], ["قارب لعبة بلاستيكي خفيف", "1f6a2"], ["منشفة", "x_sheet"]]$j$::jsonb,array['نجري التجربة فوق منشفة وعلى أرض ثابتة.','يبقى الكبير قريبًا ويساعد في حمل الصينية.','نمسح أي ماء ينسكب فورًا.','لا نستعمل أشياء صغيرة.']::text[],$j$[["نضع الصينية على منشفة بشكل مستوٍ.", "x_box"], ["نسكب قليلًا من الماء في وسطها ونلاحظ هل يتحرك.", "x_water"], ["نرفع أحد طرفي الصينية بكتاب ونلاحظ.", "i_book"], ["نضع القارب عند الطرف المرتفع ونراقب.", "1f6a2"], ["نسجل إلى أين جرى الماء.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن يجري الماء نحو الجهة المنخفضة.','بقي الماء في مكانه تقريبًا على الصينية المستوية، وعندما رفعنا طرفها جرى الماء إلى الطرف المنخفض وحمل القارب معه.','الماء سائل يتحرك إلى المكان الأدنى بفعل الجاذبية. لذلك تجري الأنهار نحو الأسفل وينزل المطر إلى الأرض.',array['الماء يجري من الأعلى إلى الأسفل.','الماء السائل يأخذ شكل الوعاء ويتحرك.','الجاذبية تشدّ الماء إلى الأسفل.']::text[],$j$[{"k": "mc", "q": "إلى أين يجري الماء على السطح المائل؟", "o": ["إلى الأسفل", "إلى الأعلى", "لا يتحرك أبدًا"], "a": 0, "ts": [1, 2]}, {"k": "odd", "i": [["ماء يجري", "x_water"], ["نهر", "1f4a7"], ["حجر", "x_stone"]], "a": 2, "why": "الحجر لا يجري مثل الماء.", "ts": [2, 3]}, {"k": "tf", "q": "الماء السائل يتحرك إلى الجهة المنخفضة.", "a": true, "ts": [1, 2, 3]}, {"k": "fill", "q": "تشدّ ___ الماء إلى الأسفل.", "o": ["الجاذبية", "الألوان", "الأصوات"], "a": 0, "ts": [3]}, {"k": "mc", "q": "ماذا حدث للقارب عندما جرى الماء؟", "o": ["تحرك مع الماء", "ارتفع إلى الأعلى", "لم يتحرك"], "a": 0, "ts": [1, 2]}]$j$::jsonb,'files/experiments/ex-water-flow-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["يطفو"]}, {"type": "media", "q": ["الماء"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',5),
('ex-primary-colors','experiment','colors','أبحث عن الألوان الأساسية','1f308',array['a3','a4','a5','a6','g1','g2']::text[],'أن أتعرف على الألوان الأساسية: الأحمر والأصفر والأزرق.',1,15,'near',array['أن أعرف الأحمر والأصفر والأزرق.','أن أصنف الأشياء حسب لونها.']::text[],$j$[["ثلاث أوراق: حمراء وصفراء وزرقاء", "x_paper"], ["أشياء ملونة من البيت (ألعاب كبيرة، قطع قماش، كتب)", "x_box"], ["أقلام تلوين", "i_pencils"]]$j$::jsonb,array['نختار أشياء كبيرة وآمنة، ولا نأخذ أشياء حادة أو صغيرة.','نبحث مع شخص كبير داخل البيت فقط.','لا نضع الأقلام أو الأوراق في الفم.']::text[],$j$[["نضع الأوراق الثلاث على الأرض.", "x_paper"], ["نبحث في البيت عن شيء أحمر ونضعه على الورقة الحمراء.", "1f441"], ["نفعل الشيء نفسه مع الأصفر ثم الأزرق.", "1f3a8"], ["نعدّ كم شيئًا وجدنا من كل لون.", "i_numbers"], ["نلوّن ثلاث دوائر بالألوان الأساسية في ورقة الملاحظات.", "i_pencils"]]$j$::jsonb,'سنجد أشياء كثيرة بكل لون من الألوان الثلاثة.','جمعنا أشياء حمراء وصفراء وزرقاء، وكان بعض الألوان أكثر من غيره في بيتنا.','الأحمر والأصفر والأزرق ألوان أساسية، ومنها نصنع ألوانًا أخرى بالمزج. وكل شيء حولنا له لون نميّزه بأعيننا.',array['الألوان الأساسية: أحمر وأصفر وأزرق.','نصنف الأشياء حسب اللون.']::text[],$j$[{"k": "match", "p": [["2b50", "أصفر"], ["1f34e", "أحمر"], ["1f4a7", "أزرق"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي هذه ألوان أساسية؟", "o": ["الأحمر والأصفر والأزرق", "الأخضر والبرتقالي والبنفسجي", "الأسود والأبيض"], "a": 0, "ts": [1, 2, 3]}, {"k": "sort", "g": ["أحمر", "أصفر"], "i": [["التفاحة", 0, "1f34e"], ["الموزة", 1, "1f34c"], ["الفراولة", 0, "1f353"], ["الشمس", 1, "2600"]], "ts": [1, 2, 3]}, {"k": "tf", "q": "الأخضر من الألوان الأساسية.", "a": false, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-primary-colors-sheet.pdf','wk-light-shadow',$j$[{"type": "cards", "cat": "colors", "sub": "أساسية", "label": "بطاقات الألوان"}, {"type": "activities", "q": ["الألوان"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',6),
('ex-mix-colors','experiment','colors','نمزج الألوان','1f3a8',array['a4','a5','a6','g1','g2','g3','g4']::text[],'أن أكتشف الألوان التي تنتج عن مزج الألوان الأساسية.',1,20,'near',array['أن مزج لونين أساسيين يعطي لونًا جديدًا.','أن أسجل ما أتوقعه وما يحدث.']::text[],$j$[["ألوان مائية أو أصبع قابلة للغسل وآمنة للأطفال (أحمر وأصفر وأزرق)", "i_palette"], ["ورق رسم سميك", "x_paper"], ["فرشاة كبيرة", "i_brush"], ["طبق ورقي للمزج", "x_sheet"], ["كوب ماء", "x_jar"], ["مئزر أو ملابس قديمة وفرش على الطاولة", "x_sheet"]]$j$::jsonb,array['نستعمل ألوانًا مكتوب عليها أنها آمنة للأطفال وقابلة للغسل.','لا نضع الألوان أو الفرشاة في الفم ولا نلمس العينين.','نغطي الطاولة ونغسل أيدينا بالماء والصابون بعد التجربة.','يبقى الكبير بجانب الطفل طوال الوقت.']::text[],$j$[["نضع نقطة صغيرة من الأحمر ونقطة من الأصفر على طبق المزج.", "i_palette"], ["نتوقع أي لون سيظهر إذا مزجناهما، ونسجل التوقع.", "i_notebook"], ["نمزجهما بالفرشاة ونلوّن ورقة بالناتج.", "i_brush"], ["نكرر مع الأصفر والأزرق، ثم مع الأحمر والأزرق.", "1f3a8"], ["نسجل اللون الناتج بجانب كل خليط.", "i_pencil"]]$j$::jsonb,'قد نتوقع أن الأحمر مع الأصفر يعطي لونًا جديدًا غير اللونين.','الأحمر مع الأصفر أعطى برتقاليًا، والأصفر مع الأزرق أعطى أخضر، والأحمر مع الأزرق أعطى بنفسجيًا (قد تختلف الدرجة حسب الألوان المستعملة).','عندما نمزج لونين نرى لونًا جديدًا يجمع بينهما. وبهذا نصنع ألوانًا كثيرة من ثلاثة ألوان أساسية فقط.',array['الأحمر + الأصفر = برتقالي.','الأصفر + الأزرق = أخضر.','الأحمر + الأزرق = بنفسجي.']::text[],$j$[{"k": "match", "p": [["1f34a", "برتقالي"], ["1f33f", "أخضر"], ["1f347", "بنفسجي"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا ينتج من مزج الأصفر والأزرق؟", "o": ["أخضر", "أحمر", "أسود"], "a": 0, "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا ينتج من مزج الأحمر والأصفر؟", "o": ["برتقالي", "أخضر", "بنفسجي"], "a": 0, "ts": [1, 2]}, {"k": "fill", "q": "الأحمر مع الأزرق يعطيان اللون ___.", "o": ["البنفسجي", "الأصفر", "الأبيض"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "نصنع ألوانًا كثيرة من الألوان الأساسية.", "a": true, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-mix-colors-sheet.pdf','wk-light-shadow',$j$[{"type": "cards", "cat": "colors", "sub": "ثانوية", "label": "بطاقات الألوان الثانوية"}, {"type": "activities", "q": ["الألوان"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',7),
('ex-marker-colors','experiment','colors','ألوان تنتقل مع الماء','1f58c',array['g2','g3','g4']::text[],'أن ألاحظ أن بعض الألوان تتكوّن من ألوان أخرى.',2,25,'near',array['أن بعض الألوان تتفرق إلى ألوان عدة عندما يصعد عليها الماء.','أن أراقب وأقارن عدة ألوان.']::text[],$j$[["شرائح من ورق المناديل جاهزة (يجهزها الكبير مسبقًا)", "x_paper"], ["أقلام تلوين مائية قابلة للغسل (أسود وبني وأخضر)", "i_pencils"], ["كوب شفاف فيه ماء قليل", "x_jar"], ["قلم رصاص لتعليق الشريحة", "i_pencil"], ["منشفة", "x_sheet"]]$j$::jsonb,array['نستعمل أقلامًا قابلة للغسل وآمنة للأطفال.','لا نضع الأقلام أو الشرائح في الفم.','الكبير يجهز الشرائح، والطفل ينفذ الخطوات تحت إشرافه.','نمسح الماء المسكوب ونغسل أيدينا.']::text[],$j$[["نرسم نقطة بكل قلم على بعد قليل من أسفل الشريحة، كل لون على شريحة.", "i_pencils"], ["نضع قليلًا من الماء في الكوب بحيث لا تغمر النقطة.", "x_jar"], ["نعلّق الشريحة بالقلم الرصاص فوق الكوب بحيث يلامس طرفها الماء فقط.", "i_pencil"], ["ننتظر ونلاحظ الماء وهو يصعد على الورق ويحمل الألوان.", "1f441"], ["نجفف الشرائح ونقارن ونرسم ما رأيناه.", "x_sheet"]]$j$::jsonb,'قد نتوقع أن كل لون يبقى كما هو.','صعد الماء على الورقة، وانفصل بعض الألوان (مثل الأسود في كثير من الأقلام) إلى عدة ألوان مختلفة.','يصعد الماء في الورقة، ويحمل معه الأصباغ. وكل صبغ يتحرك بسرعة مختلفة، فتتفرق الألوان المختلطة إلى ألوانها. وبعض الألوان تتكوّن من خليط أصباغ.',array['بعض الألوان خليط من ألوان أخرى.','الماء يمكن أن يحمل الأصباغ على الورق.','نقارن ونسجل الملاحظات.']::text[],$j$[{"k": "mc", "q": "ماذا حمل الماء معه وهو يصعد؟", "o": ["الألوان", "الرمل", "الصوت"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "كل الألوان لا تتفرق إلى ألوان أخرى أبدًا.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "بعض الألوان خليط من ___ أخرى.", "o": ["ألوان", "أحجار", "أصوات"], "a": 0, "ts": [3]}, {"k": "mc", "q": "لماذا نترك طرف الشريحة في الماء فقط؟", "o": ["حتى لا تذوب النقطة في الماء مباشرة", "لنوفر الماء", "لا سبب"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-marker-colors-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["الألوان"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',8),
('ex-plant-parts','experiment','plants','أجزاء النبات','x_plant',array['a3','a4','a5','a6','g1','g2']::text[],'أن أتعرف على أجزاء النبات وأسمّيها.',1,15,'near',array['أن للنبات جذرًا وساقًا وأوراقًا وزهرة.','أن أراقب نباتًا حقيقيًا بعيني.']::text[],$j$[["نبتة صغيرة في أصيص", "x_pot"], ["ورقة وصورة لأجزاء النبات", "x_paper"], ["أقلام تلوين", "i_pencils"]]$j$::jsonb,array['ننظر ونلمس الورقة برفق فقط، ولا نقطف ولا نكسر النبتة.','لا نضع النبات أو التراب في الفم، ونغسل أيدينا بعد اللمس.','نتأكد مع الكبير أن النبتة آمنة وليست شائكة.']::text[],$j$[["نضع النبتة أمامنا ونحدد الورقة والساق.", "x_leaf"], ["نلمس الورقة بلطف ونصفها: ناعمة أم خشنة؟", "x_hand"], ["ننظر إلى التراب ونعرف أن الجذر يكون تحته.", "x_soil"], ["نرسم النبتة ونكتب اسم كل جزء.", "i_pencil"]]$j$::jsonb,'سنجد ورقة وساقًا فوق التراب، والجذر تحت التراب.','رأينا الأوراق والساق، ولم نرَ الجذر لأنه تحت التراب.','الجذر يثبّت النبات ويمتص الماء، والساق تحمله، والأوراق تصنع غذاءه بمساعدة الضوء.',array['أجزاء النبات: جذر وساق وأوراق وزهرة.','لكل جزء وظيفة.']::text[],$j$[{"k": "mc", "q": "أي جزء يمتص الماء من التراب؟", "o": ["الجذر", "الورقة", "الزهرة"], "a": 0, "ts": [1, 2]}, {"k": "match", "p": [["x_leaf", "ورقة"], ["x_soil", "تراب"], ["x_plant", "نبتة"]], "ts": [1, 2]}, {"k": "tf", "q": "الجذر يكون فوق التراب دائمًا.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "الساق تحمل ___ النبات.", "o": ["أوراق", "أحجار", "أصوات"], "a": 0, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-plant-parts-sheet.pdf','wk-plant-parts',$j$[{"type": "activities", "q": ["النبات"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',9),
('ex-bean-grow','experiment','plants','كيف تنمو البذرة؟','x_seed',array['a5','a6','g1','g2','g3','g4']::text[],'أن أراقب نمو بذرة فول عدة أيام وأسجل التغيرات.',2,10,'near',array['أن البذرة تنبت وتنمو إذا توفر لها الماء والدفء.','أن أسجل التغير يوميًا.']::text[],$j$[["حبتا فول أو فاصولياء كبيرة", "x_seed"], ["قطن مبلل", "x_sheet"], ["كيس شفاف أو كوب شفاف", "x_jar"], ["ورقة تسجيل", "i_notebook"], ["نافذة مضيئة", "x_sunrise"]]$j$::jsonb,array['البذور ليست طعامًا في التجربة ولا توضع في الفم.','نغسل أيدينا بعد لمس البذور والقطن.','نحافظ على الكيس بعيدًا عن وجه الطفل الصغير.','يبقى الكبير بجانب الطفل في كل مرة.']::text[],$j$[["نبلل القطن ونضعه في الكوب ونضع البذرة بين القطن والجدار.", "x_seed"], ["نضع الكوب بجانب النافذة.", "x_sunrise"], ["كل يوم نلاحظ البذرة ونحافظ على رطوبة القطن.", "x_water"], ["نرسم ما نراه يوميًا.", "i_pencil"], ["بعد أيام نقيس طول الجذر بمسطرة.", "i_ruler"]]$j$::jsonb,'سنرى البذرة تنتفخ ثم يخرج منها جذر صغير.','انتفخت البذرة، ثم خرج جذر أبيض، ثم ساق صغيرة تتجه إلى الأعلى.','البذرة فيها نبتة صغيرة وغذاء. وعند توفر الماء والدفء تنبت، فيخرج الجذر أولًا ثم الساق.',array['البذرة تحتاج ماءً ودفئًا لتنبت.','يخرج الجذر قبل الساق.','نسجل التغير يوميًا.']::text[],$j$[{"k": "mc", "q": "ما الذي يخرج من البذرة أولًا؟", "o": ["الجذر", "الزهرة", "الثمرة"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "البذرة تنبت بدون ماء.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "تحتاج البذرة إلى ___ لتنبت.", "o": ["الماء", "الحجارة", "الألوان"], "a": 0, "ts": [2, 3]}, {"k": "mc", "q": "لماذا نرسم البذرة كل يوم؟", "o": ["لنلاحظ التغير", "للتسلية فقط", "لا سبب"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-bean-grow-sheet.pdf','wk-plant-needs',$j$[{"type": "activities", "q": ["النبات"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',10),
('ex-plant-needs','experiment','plants','ماذا يحتاج النبات؟','x_pot',array['g1','g2','g3','g4']::text[],'أن أقارن بين نبتتين لأعرف حاجة النبات إلى الماء والضوء.',3,10,'near',array['أن النبات يحتاج إلى الماء والضوء.','أن أغيّر شيئًا واحدًا فقط في التجربة.']::text[],$j$[["نبتتان متشابهتان", "x_pot"], ["كوب ماء", "x_jar"], ["مكان مضيء ومكان معتم داخل البيت", "x_sunrise"], ["جدول ملاحظات", "i_notebook"]]$j$::jsonb,array['نختار نباتات غير مؤذية وغير شائكة.','لا نترك نبتة بلا ماء بشكل يضرّها: ننهي التجربة بعد أسبوع ونعتني بها.','نغسل أيدينا بعد لمس التراب.','يبقى الكبير بجانب الطفل.']::text[],$j$[["نضع الأولى في مكان مضيء ونسقيها كل يوم.", "x_water"], ["نضع الثانية في مكان معتم قليلًا ولا نسقيها لعدة أيام.", "x_pot"], ["نسجل الشكل واللون كل يوم.", "i_notebook"], ["بعد أسبوع نقارن ثم نسقي النبتة الثانية ونضعها في الضوء.", "x_water"]]$j$::jsonb,'قد نتوقع أن تذبل النبتة التي بلا ماء وضوء.','بقيت النبتة المسقيّة في الضوء خضراء، وذبلت أوراق الأخرى. وبعد أن اعتنينا بها بدأت تنتعش.','النبات يحتاج إلى الماء والضوء ليصنع غذاءه. وبدونهما يضعف ويذبل.',array['النبات يحتاج إلى الماء والضوء.','نغيّر عاملًا واحدًا فقط لنقارن.','نعتني بالنبات بعد التجربة.']::text[],$j$[{"k": "mc", "q": "ماذا يحتاج النبات ليبقى أخضر؟", "o": ["ماء وضوء", "ظلام فقط", "حجارة"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "النبات الذي بلا ماء يبقى أخضر طويلًا.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "نغيّر ___ واحدًا فقط في التجربة.", "o": ["شيئًا", "عشرة أشياء", "كل شيء"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-plant-needs-sheet.pdf','wk-plant-needs',$j$[{"type": "activities", "q": ["النبات"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',11),
('ex-shadow-hand','experiment','light','أين الظل؟','1f4a1',array['a3','a4','a5','a6','g1','g2']::text[],'أن أكتشف كيف يتكوّن الظل.',1,15,'near',array['أن الظل يظهر عندما يحجب شيء الضوء.','أن الظل يكون في الجهة المقابلة للضوء.']::text[],$j$[["مصباح يدوي", "i_lamp"], ["لعبة كبيرة", "1f9f8"], ["حائط أبيض أو ورقة كبيرة", "x_paper"], ["غرفة خافتة الإضاءة", "1f319"]]$j$::jsonb,array['لا نوجّه المصباح إلى العين أبدًا.','الكبير يمسك المصباح ويشغّله للأعمار الصغيرة.','نجري التجربة في مكان لا نتعثر فيه.']::text[],$j$[["نطفئ الأضواء ونوجه المصباح إلى الحائط ونرى دائرة الضوء.", "i_lamp"], ["نضع اللعبة بين المصباح والحائط.", "1f9f8"], ["نلاحظ الظل خلف اللعبة.", "1f441"], ["نحرك اللعبة ونرى كيف يتحرك الظل.", "x_hand"], ["نرسم الظل.", "i_pencil"]]$j$::jsonb,'سيظهر ظل اللعبة على الحائط.','ظهر ظل داكن للعبة على الحائط، وتحرك عندما حركنا اللعبة.','الضوء يسير في خط مستقيم، وعندما تمنعه اللعبة من المرور يظهر خلفها مكان مظلم هو الظل.',array['الظل يتكون عندما يحجب شيء الضوء.','الظل في الجهة المقابلة للضوء.']::text[],$j$[{"k": "mc", "q": "متى يظهر الظل؟", "o": ["عندما يحجب شيء الضوء", "عندما لا يوجد جسم", "في الظلام الكامل"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "الظل يكون أمام المصباح مباشرة.", "a": false, "ts": [2, 3]}, {"k": "match", "p": [["i_lamp", "مصدر ضوء"], ["1f9f8", "جسم"], ["1f319", "ظلام"]], "ts": [1, 2]}, {"k": "fill", "q": "الضوء يسير في خط ___.", "o": ["مستقيم", "مموج", "دائري"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-shadow-hand-sheet.pdf','wk-light-shadow',$j$[{"type": "activities", "q": ["الظل"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',12),
('ex-shadow-size','experiment','light','يكبر الظل ويصغر','1f4a1',array['a6','g1','g2','g3','g4']::text[],'أن أكتشف كيف يتغير حجم الظل بتغيّر المسافة.',2,20,'near',array['أن الظل يكبر عندما يقترب الجسم من المصباح.','أن أقيس وأقارن.']::text[],$j$[["مصباح يدوي", "i_lamp"], ["لعبة كبيرة", "1f9f8"], ["حائط أبيض", "x_paper"], ["مسطرة", "i_ruler"], ["ورقة تسجيل", "i_notebook"]]$j$::jsonb,array['لا نوجه المصباح إلى العين.','نبقي المصباح في مكانه ثابتًا بيد الكبير.','ننتبه للأرض حتى لا نتعثر.']::text[],$j$[["نثبت المصباح ونوجهه إلى الحائط.", "i_lamp"], ["نضع اللعبة بعيدة عن المصباح ونقيس طول الظل.", "i_ruler"], ["نقرّب اللعبة ونقيس مرة أخرى.", "i_ruler"], ["نسجل القياسين ونقارن.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن يكبر الظل عندما نقرب اللعبة من المصباح.','كلما اقتربت اللعبة من المصباح صار ظلها أكبر، وكلما ابتعدت صار أصغر.','عند الاقتراب من المصباح يحجب الجسم عددًا أكبر من أشعة الضوء، فيكبر الظل.',array['الظل يكبر عند الاقتراب من المصباح.','الظل يصغر عند الابتعاد.']::text[],$j$[{"k": "mc", "q": "ماذا يحدث للظل عند الاقتراب من المصباح؟", "o": ["يكبر", "يصغر", "يختفي"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "الظل يصغر عند الابتعاد عن المصباح.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "كلما ابتعد الجسم عن المصباح صار الظل ___.", "o": ["أصغر", "أكبر", "أحمر"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-shadow-size-sheet.pdf','wk-light-shadow',$j$[{"type": "activities", "q": ["الظل"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',13),
('ex-light-sources','experiment','light','ما مصدر الضوء؟','2600',array['a3','a4','a5','a6','g1','g2']::text[],'أن أميّز مصادر الضوء من الأشياء التي لا تصدر ضوءًا.',1,15,'near',array['أن الشمس والمصباح مصدران للضوء.','أن القمر والكتاب لا يصدران ضوءًا بأنفسهما.']::text[],$j$[["صور أو أشياء: مصباح، شمس، قمر، كتاب، حجر", "x_paper"], ["مصباح يدوي", "i_lamp"], ["ورقتان للتصنيف: يضيء / لا يضيء", "x_sheet"]]$j$::jsonb,array['لا ننظر إلى الشمس مباشرة أبدًا.','لا نوجه المصباح إلى العين.','نعمل مع شخص كبير.']::text[],$j$[["نضع الصور أمامنا.", "x_paper"], ["نسأل: هل يصدر الضوء بنفسه؟", "1f4a1"], ["نضع المصباح والشمس في ورقة يضيء.", "2600"], ["نضع الكتاب والحجر في ورقة لا يضيء.", "x_stone"]]$j$::jsonb,'الشمس والمصباح يضيئان بأنفسهما.','وضعنا الشمس والمصباح في مجموعة المصادر، والكتاب والحجر في المجموعة الأخرى.','مصدر الضوء يصدر الضوء بنفسه، أما الأشياء الأخرى فنراها لأن الضوء يرتد منها إلى أعيننا.',array['الشمس والمصباح مصادر ضوء.','نرى الأشياء لأن الضوء يرتد عنها.']::text[],$j$[{"k": "sort", "g": ["يصدر ضوءًا", "لا يصدر"], "i": [["الشمس", 0, "2600"], ["المصباح", 0, "i_lamp"], ["الحجر", 1, "x_stone"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي هذه مصدر ضوء؟", "o": ["الشمس", "الكتاب", "الحجر"], "a": 0, "ts": [1, 2]}, {"k": "tf", "q": "القمر يصنع ضوءه بنفسه.", "a": false, "ts": [3]}]$j$::jsonb,'files/experiments/ex-light-sources-sheet.pdf','wk-light-shadow',$j$[{"type": "activities", "q": ["الضوء"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',14),
('ex-sun-shadow','experiment','light','ظل الشمس خلال اليوم','2600',array['g1','g2','g3','g4']::text[],'أن ألاحظ كيف يتغير طول الظل وموضعه خلال النهار.',3,30,'near',array['أن الظل يتغير خلال النهار.','أن أسجل ملاحظات في أوقات مختلفة.']::text[],$j$[["عصا أو لعبة طويلة ثابتة في أصيص", "x_pot"], ["طبشور للتعليم على الأرض", "i_pencil"], ["مسطرة", "i_ruler"], ["جدول ملاحظات", "i_notebook"]]$j$::jsonb,array['لا ننظر إلى الشمس مباشرة أبدًا.','نجري التجربة في ساحة آمنة مع شخص كبير.','نبتعد عن الطريق.']::text[],$j$[["نضع العصا في مكان مشمس ثابت.", "x_pot"], ["نعلّم نهاية الظل بالطبشور في الصباح ونقيسه.", "i_ruler"], ["نكرر بعد الظهر ثم قبل المساء.", "x_sunrise"], ["نقارن الأطوال والاتجاهات.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن يتغير الظل خلال اليوم.','كان الظل طويلًا صباحًا وأقصر عند الظهر ثم طال مساءً، وتغيّر اتجاهه.','تتحرك الشمس في السماء بسبب دوران الأرض، فيتغير زاوية الضوء فيتغير طول الظل واتجاهه.',array['الظل يتغير خلال اليوم.','الظل أقصر ما يكون وقت الظهر.']::text[],$j$[{"k": "mc", "q": "متى يكون الظل أقصر؟", "o": ["وقت الظهر", "عند الشروق", "عند الغروب"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "الظل لا يتغير أبدًا خلال النهار.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "يتغير الظل لأن ___ تبدو متحركة في السماء.", "o": ["الشمس", "الكتب", "الحجارة"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-sun-shadow-sheet.pdf','wk-sun',$j$[{"type": "activities", "q": ["الشمس"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',15),
('ex-air-cup','experiment','air','هل في الكوب هواء؟','1f4a8',array['a6','g1','g2','g3','g4']::text[],'أن أكتشف أن الهواء موجود ويشغل مكانًا.',2,15,'near',array['أن الهواء موجود وإن لم نره.','أن الهواء يشغل مكانًا.']::text[],$j$[["وعاء شفاف كبير فيه ماء", "x_bucket"], ["كوب بلاستيكي شفاف", "x_jar"], ["ورقة صغيرة", "x_paper"], ["منشفة", "x_sheet"]]$j$::jsonb,array['نفرش منشفة ونمسح الماء المسكوب.','نستعمل كوبًا بلاستيكيًا فقط.','يبقى الكبير بجانب الطفل.']::text[],$j$[["نضع الورقة داخل الكوب بحيث لا تسقط.", "x_paper"], ["نقلب الكوب ونغمره مستقيمًا في الماء.", "x_jar"], ["نرفعه بهدوء ونفحص الورقة.", "1f441"], ["نسجل هل ابتلت الورقة.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن تبتل الورقة.','بقيت الورقة جافة تقريبًا لأن الهواء داخل الكوب منع الماء من الدخول.','الهواء شيء حقيقي يشغل مكانًا، ولذلك لم يدخل الماء إلى الكوب المقلوب.',array['الهواء موجود ويشغل مكانًا.','الهواء لا يُرى لكنه يمنع الماء من الدخول.']::text[],$j$[{"k": "mc", "q": "لماذا بقيت الورقة جافة؟", "o": ["الهواء منع الماء", "الماء ساخن", "الورقة سميكة"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "الهواء لا يشغل مكانًا.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "الكوب المقلوب فيه ___.", "o": ["هواء", "رمل", "ثلج"], "a": 0, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-air-cup-sheet.pdf','wk-air',$j$[{"type": "activities", "q": ["الهواء"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',16),
