('ex-weather-log','experiment','air','سجل الطقس','1f308',array['a6','g1','g2','g3','g4']::text[],'أن أراقب حالة الطقس كل يوم وأسجلها.',2,10,'near',array['أن للطقس حالات: مشمس وغائم وماطر وعاصف.','أن أسجل وأقارن لأيام.']::text[],$j$[["جدول الطقس لأسبوع", "i_notebook"], ["أقلام تلوين", "i_pencils"], ["نافذة نرى منها السماء", "x_sunrise"]]$j$::jsonb,array['نراقب من النافذة أو من مكان آمن مع الكبير.','لا ننظر إلى الشمس مباشرة.','لا نخرج في الأجواء العاصفة.']::text[],$j$[["كل يوم ننظر من النافذة إلى السماء.", "x_sunrise"], ["نسأل: هل الجو مشمس أم غائم أم ماطر؟", "2601"], ["نلوّن خانة اليوم بالرمز المناسب.", "i_pencils"], ["بعد أسبوع نعدّ الأيام من كل نوع.", "i_numbers"]]$j$::jsonb,'ستتغير حالة الطقس من يوم إلى آخر.','سجلنا أيامًا مشمسة وأخرى غائمة، وربما ماطرة.','الطقس يتغير بسبب حركة الهواء والسحب وحرارة الشمس. ونسجل الأيام لنعرف الأكثر تكرارًا.',array['للطقس حالات مختلفة.','نسجل ملاحظاتنا بالرسم والعد.']::text[],$j$[{"k": "match", "p": [["2600", "مشمس"], ["2601", "غائم"], ["1f327", "ماطر"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "ماذا نفعل في سجل الطقس؟", "o": ["نسجل حالة الجو كل يوم", "نرسم الأحجار", "نقيس الصوت"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "الطقس لا يتغير أبدًا.", "a": false, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-weather-log-sheet.pdf','wk-weather-seasons',$j$[{"type": "activities", "q": ["الطقس"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',18),
('ex-wind-ribbon','experiment','air','شريط الريح','1fa81',array['a5','a6','g1','g2','g3','g4']::text[],'أن أصنع مؤشرًا بسيطًا يدل على وجود الريح واتجاهها.',2,20,'near',array['أن شريطًا خفيفًا يبين اتجاه الريح.','أن الريح تختلف في قوتها.']::text[],$j$[["شريط قماش أو ورق خفيف طويل", "x_sheet"], ["عصا خشبية كبيرة وسميكة بلا رأس مدبب", "x_stone"], ["شريط لاصق", "x_paper"]]$j$::jsonb,array['نختار عصا ملساء بلا أطراف حادة.','نستعمل المؤشر في ساحة آمنة مع شخص كبير.','لا نخرج في الأجواء العاصفة.']::text[],$j$[["يثبت الكبير الشريط بالعصا باللاصق.", "x_paper"], ["نخرج إلى مكان آمن ونمسك العصا.", "x_hand"], ["نلاحظ اتجاه الشريط.", "x_wind"], ["نسجل الاتجاه وقوة الريح: ضعيفة أم قوية.", "i_notebook"]]$j$::jsonb,'سيتحرك الشريط عندما تهب الريح.','تحرك الشريط مع الريح وأشار إلى الجهة التي تذهب إليها.','الريح هواء متحرك يدفع الشريط الخفيف. وكلما اشتدت الريح ارتفع الشريط واهتز أكثر.',array['الريح هواء متحرك.','الشريط يدل على اتجاه الريح.']::text[],$j$[{"k": "mc", "q": "ماذا يبين الشريط؟", "o": ["اتجاه الريح", "حرارة الماء", "لون السماء"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "عندما لا توجد ريح يبقى الشريط ساكنًا.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "الريح هواء ___.", "o": ["متحرك", "ساكن", "صلب"], "a": 0, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-wind-ribbon-sheet.pdf','wk-air',$j$[{"type": "activities", "q": ["الريح"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',19),
('ex-sound-vibe','experiment','daily','الصوت يهتز','i_sound',array['a5','a6','g1','g2','g3','g4']::text[],'أن أرى أن الصوت ينتج عن الاهتزاز.',2,15,'near',array['أن الصوت ينتج من اهتزاز.','أن أشعر بالاهتزاز بيدي.']::text[],$j$[["علبة معدنية كبيرة فارغة ونظيفة بلا حواف حادة (يجهزها الكبير)", "x_can"], ["طبل لعبة", "1f941"], ["ورق أو حبوب كبيرة كالفول", "x_seed"]]$j$::jsonb,array['لا نستعمل علبة بحواف حادة أبدًا.','لا نضع الحبوب في الفم.','نبتعد عن الأذن بالأصوات العالية.']::text[],$j$[["نضع الطبل على الطاولة ونطرقه برفق.", "1f941"], ["نضع يدنا فوقه ونحس بالاهتزاز.", "x_hand"], ["نضع حبات الفول على الطبل ونطرق قربه.", "x_seed"], ["نلاحظ الحبوب وهي تتحرك.", "1f441"]]$j$::jsonb,'قد نتوقع أن نحس بشيء عند صدور الصوت.','أحسسنا بالاهتزاز في اليد، وتحركت الحبوب عندما صدر الصوت.','الأجسام عندما تصدر صوتًا تهتز اهتزازات سريعة، وهذه الاهتزازات تصل إلى آذاننا فنسمع.',array['الصوت ينتج من الاهتزاز.','نحس بالاهتزاز بأيدينا.']::text[],$j$[{"k": "mc", "q": "ما سبب الصوت؟", "o": ["الاهتزاز", "الضوء", "اللون"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "تتحرك الحبوب عند صدور الصوت.", "a": true, "ts": [2, 3]}, {"k": "match", "p": [["1f941", "طبل"], ["x_ear", "أذن"], ["x_hand", "يد"]], "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-sound-vibe-sheet.pdf','wk-sound',$j$[{"type": "activities", "q": ["الصوت"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',20),
('ex-magnet','experiment','daily','المغناطيس يجذب','1f52c',array['g1','g2','g3','g4']::text[],'أن أكتشف الأشياء التي يجذبها المغناطيس.',3,20,'required',array['أن المغناطيس يجذب بعض المعادن.','أن أصنّف الأشياء إلى تنجذب وتنفر.']::text[],$j$[["مغناطيس تعليمي كبير للأطفال", "1f52c"], ["أشياء كبيرة: مفتاح كبير، قطعة بلاستيك، ورقة، ملعقة خشبية", "x_box"], ["جدول تصنيف", "i_notebook"]]$j$::jsonb,array['الكبير يشرف طوال الوقت، ولا يستعمل الطفل المغناطيس وحده.','نستعمل مغناطيسًا كبيرًا تعليميًا فقط، ولا مغانط صغيرة قد تُبتلع.','نبعد المغناطيس عن الهواتف والبطاقات.','لا نضع أي شيء في الفم.']::text[],$j$[["نتوقع أي الأشياء سيجذبها المغناطيس.", "i_notebook"], ["نقرّب المغناطيس من كل شيء بالتتالي.", "1f52c"], ["نضع ما انجذب في مجموعة، وما لم ينجذب في أخرى.", "x_box"], ["نسجل النتائج.", "i_pencil"]]$j$::jsonb,'قد نتوقع أن بعض الأشياء فقط ستنجذب.','انجذب المفتاح الحديدي، ولم تنجذب الورقة والبلاستيك والخشب.','المغناطيس يجذب الأشياء المصنوعة من الحديد وبعض المعادن، ولا يجذب الورق والخشب والبلاستيك.',array['المغناطيس يجذب الحديد.','لا يجذب كل شيء.','نصنف الأشياء بالتجربة.']::text[],$j$[{"k": "sort", "g": ["ينجذب", "لا ينجذب"], "i": [["مفتاح", 0, "1f52c"], ["ورقة", 1, "x_paper"], ["خشب", 1, "x_spoon"]], "ts": [2, 3]}, {"k": "tf", "q": "المغناطيس يجذب الورق.", "a": false, "ts": [3]}, {"k": "mc", "q": "أي شيء يجذبه المغناطيس؟", "o": ["الحديد", "الخشب", "الورق"], "a": 0, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-magnet-sheet.pdf',null,$j$[{"type": "activities", "q": ["المغناطيس"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',21),
('ex-balance','experiment','daily','ميزان الأشياء','x_sheet',array['a5','a6','g1','g2','g3','g4']::text[],'أن أتعلم معنى التوازن عند مقارنة الأثقال.',2,20,'near',array['أن التوازن يحدث عندما يتساوى الثقلان.','أن أقارن بين الثقيل والخفيف.']::text[],$j$[["مسطرة كبيرة وقلم أو مكعب عريض كنقطة ارتكاز", "i_ruler"], ["مكعبات خشب كبيرة", "i_blocks"], ["ورقة تسجيل", "i_notebook"]]$j$::jsonb,array['نستعمل مكعبات كبيرة فقط.','نجلس أمام الطاولة بثبات.','ننتبه لأصابعنا عند وضع الأشياء.']::text[],$j$[["نضع المسطرة على المكعب العريض بحيث تتوازن.", "i_ruler"], ["نضع مكعبًا على طرف ونراقب.", "i_blocks"], ["نضع مكعبًا مماثلًا على الطرف الآخر.", "i_blocks"], ["نسجل ماذا حدث.", "i_notebook"]]$j$::jsonb,'سيميل الطرف الأثقل إلى الأسفل.','مالت المسطرة نحو الطرف الأثقل، وعندما وضعنا ثقلين متساويين تساوت.','يتوازن الجسم عندما يتساوى الثقل على جانبيه. والطرف الأثقل يميل إلى الأسفل.',array['التوازن يعني تساوي الثقلين.','الأثقل يميل إلى الأسفل.']::text[],$j$[{"k": "mc", "q": "ماذا يحدث عندما يتساوى الثقلان؟", "o": ["يتوازن", "يسقط", "يختفي"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "الطرف الأثقل يرتفع إلى الأعلى.", "a": false, "ts": [2, 3]}, {"k": "fill", "q": "يحدث ___ عندما يتساوى الثقلان.", "o": ["التوازن", "الغرق", "الذوبان"], "a": 0, "ts": [3]}]$j$::jsonb,'files/experiments/ex-balance-sheet.pdf',null,$j$[{"type": "activities", "q": ["التوازن"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',22),
('ex-sort-props','experiment','daily','نصنف حسب الخصائص','x_box',array['a3','a4','a5','a6','g1','g2']::text[],'أن أصنّف الأشياء حسب خصائصها مثل الصلابة والنعومة.',1,15,'near',array['أن للأشياء خصائص نصفها بحواسنا.','أن أصنّف إلى مجموعتين.']::text[],$j$[["أشياء كبيرة آمنة: إسفنجة، كتاب، لعبة قماش، كوب بلاستيكي، حجر كبير", "x_box"], ["ورقتان للتصنيف: ناعم / صلب", "x_sheet"]]$j$::jsonb,array['نختار أشياء كبيرة وآمنة لا يمكن بلعها.','نلمس الأشياء بأيدينا فقط ولا نضعها في الفم.','نغسل أيدينا بعد التجربة.']::text[],$j$[["نضع الأشياء أمامنا.", "x_box"], ["نلمس كل شيء ونصفه: ناعم أم صلب؟", "x_hand"], ["نضعه في الورقة المناسبة.", "x_sheet"], ["نعد كل مجموعة.", "i_numbers"]]$j$::jsonb,'سنجد أن بعض الأشياء ناعمة وبعضها صلب.','وضعنا الإسفنجة وقماش اللعبة في الناعم، والحجر والكوب في الصلب.','لكل مادة خصائص مثل الصلابة أو النعومة، ونستعملها لنختار المادة المناسبة لكل استخدام.',array['الأشياء لها خصائص.','نصنف حسب الخصائص.']::text[],$j$[{"k": "sort", "g": ["ناعم", "صلب"], "i": [["إسفنجة", 0, "x_sheet"], ["حجر", 1, "x_stone"], ["لعبة قماش", 0, "1f9f8"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "كيف نعرف أن الشيء ناعم؟", "o": ["نلمسه", "نشمه", "نتذوقه"], "a": 0, "ts": [1, 2, 3]}, {"k": "tf", "q": "نضع الأشياء في الفم لنعرف خصائصها.", "a": false, "ts": [1, 2, 3]}]$j$::jsonb,'files/experiments/ex-sort-props-sheet.pdf','wk-senses',$j$[{"type": "activities", "q": ["تصنيف"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',23),
('ex-boat-load','experiment','water','قارب يحمل حمولة','1f6a2',array['a6','g1','g2','g3','g4']::text[],'أن أكتشف كم حمولة يحملها قارب يطفو على الماء.',2,20,'near',array['أن القارب الأوسع يحمل أكثر.','أن أعدّ وأقارن.']::text[],$j$[["حوض فيه ماء", "x_bucket"], ["علبة بلاستيكية نظيفة بلا حواف حادة كقارب", "x_box"], ["مكعبات خشب كبيرة", "i_blocks"], ["منشفة", "x_sheet"]]$j$::jsonb,array['نفرش منشفة ونمسح الماء المسكوب.','نستعمل مكعبات كبيرة لا يمكن بلعها.','يبقى الكبير قرب الطفل وهو بجانب الماء.','نغسل أيدينا بعد التجربة.']::text[],$j$[["نضع العلبة في الماء ونتأكد أنها تطفو.", "x_box"], ["نتوقع كم مكعبًا ستحمل قبل أن تغرق.", "i_notebook"], ["نضع المكعبات واحدًا واحدًا برفق ونعدّ.", "i_blocks"], ["نسجل العدد عند أن تقترب من الغرق.", "i_numbers"]]$j$::jsonb,'سيحمل القارب عددًا من المكعبات.','حملت العلبة عدة مكعبات قبل أن تمتلئ بالماء وتغرق.','يطفو القارب لأنه يدفع كمية من الماء بحجمه، فيدفعه الماء إلى الأعلى. وكلما كان أوسع حمل أكثر.',array['القارب يطفو بسبب شكله وما فيه من هواء.','الأوسع يحمل أكثر.']::text[],$j$[{"k": "mc", "q": "لماذا طفت العلبة؟", "o": ["فيها هواء وهي واسعة", "لأنها ثقيلة جدًا", "لأنها حمراء"], "a": 0, "ts": [2, 3]}, {"k": "tf", "q": "القارب الأوسع يحمل أكثر عادة.", "a": true, "ts": [2, 3]}, {"k": "fill", "q": "نعدّ ___ التي حملها القارب.", "o": ["المكعبات", "الأصوات", "الألوان"], "a": 0, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-boat-load-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["يطفو"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',24),
('ex-sponge','experiment','water','من يمتص الماء؟','x_sheet',array['a4','a5','a6','g1','g2']::text[],'أن أقارن بين أشياء تمتص الماء وأشياء لا تمتصه.',1,15,'near',array['أن بعض الأشياء تمتص الماء.','أن أقارن بين المواد.']::text[],$j$[["إسفنجة كبيرة", "x_sheet"], ["منديل ورقي", "x_paper"], ["طبق بلاستيكي", "x_sheet"], ["كوب ماء صغير", "x_jar"], ["صينية", "x_box"]]$j$::jsonb,array['نجري التجربة فوق صينية ومنشفة.','لا نشرب الماء ولا نضع الأشياء في الفم.','يبقى الكبير بجانب الطفل.']::text[],$j$[["نضع الأشياء الثلاثة على الصينية.", "x_box"], ["نسكب قليلًا من الماء على كل شيء.", "x_water"], ["نلاحظ أي شيء امتص الماء وأيها بقي الماء فوقه.", "1f441"], ["نسجل النتيجة.", "i_notebook"]]$j$::jsonb,'قد نتوقع أن يمتص بعضها الماء.','امتصت الإسفنجة والمنديل الماء، وبقي الماء فوق الطبق البلاستيكي.','في الإسفنجة والمنديل فراغات صغيرة كثيرة تسحب الماء إليها، أما الطبق فسطحه لا يسمح بدخول الماء.',array['بعض المواد تمتص الماء.','لكل مادة خاصية.']::text[],$j$[{"k": "sort", "g": ["يمتص", "لا يمتص"], "i": [["إسفنجة", 0, "x_sheet"], ["منديل", 0, "x_paper"], ["طبق", 1, "x_sheet"]], "ts": [1, 2, 3]}, {"k": "mc", "q": "أي شيء امتص الماء؟", "o": ["الإسفنجة", "الطبق البلاستيكي", "الحجر"], "a": 0, "ts": [1, 2, 3]}, {"k": "tf", "q": "الطبق البلاستيكي يمتص الماء مثل الإسفنجة.", "a": false, "ts": [2, 3]}]$j$::jsonb,'files/experiments/ex-sponge-sheet.pdf','wk-water',$j$[{"type": "activities", "q": ["الماء"]}]$j$::jsonb,'','كُتبت التجربة برمجيًا وفُحصت بقائمة سلامة زاد (لا لهب ولا حرارة ولا أدوات حادة ولا مواد كيميائية ولا تذوق ولا استنشاق)، وراجعها فريق زاد مراجعة عامة. لم يراجعها مختص علمي أو تربوي بعد.',true,'published',25),
